      "content": "{\n  \"name\": \"dsh-web\",\n  \"version\": \"0.4.11\",\n  \"private\": true,\n  \"description\": \"DeepSeek Harness Web GUI 插件全家桶。皮肤、宠物与社区插件索引已拆分为独立仓库（dsh-skins / dsh-pet / dsh-community-plugins），本仓通过 npm 包内置它们。\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./packages/dsh-web-all/cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"package.json\",\n    \"packages/dsh-web-all/cordis.patch.yml\"\n  ],\n  \"dependencies\": {\n    \"@linxin666/dsh-web-all\": \"^0.4.11\"\n  },\n  \"scripts\": {\n    \"build\": \"pnpm -r build\",\n    \"dev:watch\": \"node scripts/dev-watch.mjs\",\n    \"test\": \"pnpm -r test\",\n    \"test:standards\": \"node scripts/test-standards.mjs --check\",\n    \"test:standards:write\": \"node scripts/test-standards.mjs --write-baseline\",\n    \"typecheck\": \"pnpm -r typecheck\",\n    \"aggregate:check\": \"node scripts/aggregate.mjs --check\",\n    \"runtime-deps:check\": \"node scripts/runtime-deps-check.mjs\",\n    \"libs:check\": \"node scripts/lib-artifact-check.mjs\",\n    \"libs:write\": \"node scripts/lib-artifact-check.mjs --write\",\n    \"i18n:check\": \"node scripts/i18n-audit.mjs --check\",\n    \"emoji:check\": \"node scripts/emoji-audit.mjs\",\n    \"lint\": \"oxlint --deny-warnings --format=unix .\",\n    \"test:scripts\": \"node --test scripts/*.test.mjs\",\n    \"test:mount\": \"bash scripts/e2e-mount.sh\",\n    \"coverage:check\": \"node scripts/coverage-gate.mjs\",\n    \"coverage:write\": \"node scripts/coverage-gate.mjs --write-baseline\",\n    \"pr:review\": \"node scripts/pr-review.mjs\",\n    \"docs:check\": \"node scripts/verify-docs.mjs\",\n    \"docs:list\": \"node scripts/verify-docs.mjs --list\",\n    \"docs:write-pair\": \"node scripts/verify-docs.mjs --write\",\n    \"sync-shared\": \"node scripts/sync-shared.mjs\",\n    \"sync-shared:check\": \"node scripts/sync-shared.mjs --check\",\n    \"market:build\": \"node scripts/market-build\",\n    \"market:check\": \"node scripts/market-